<script setup>
import { reactive, ref } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MDialog from '../../../components/mds/MDialog.vue'; import MInput from '../../../components/mds/MInput.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import { toEventDraft, toEventPayload } from '../domain/event-write.mjs';
const props = defineProps({ saving: Boolean, error: String, safeAreaStyle: Object }); const emit = defineEmits(['cancel', 'save']); const draft = reactive(toEventDraft()); const discard = ref(false); const localError = ref(''); const modes = [{ value: 'host', label: 'Tổ chức' }, { value: 'join', label: 'Tham gia' }]; const statuses = ['', 'Đang chuẩn bị', 'Đã diễn ra', 'Đã hủy'].map((value) => ({ value, label: value || 'Chọn trạng thái' })); function submit() { try { localError.value = ''; emit('save', toEventPayload(draft)); } catch (error) { localError.value = error.message; } }
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar title="Thêm sự kiện" @back="discard = true"><template #actions><MButton variant="link" @click="discard = true">Hủy</MButton></template></MMobileTopBar><div class="min-h-0 flex-1 overflow-y-auto"><div class="mds-mobile-gutter-x space-y-4 py-4"><label><span class="mb-1 block text-[13px] font-medium">Tên sự kiện *</span><MInput v-model="draft.name" /></label><label><span class="mb-1 block text-[13px] font-medium">Hình thức</span><MSelect v-model="draft.mode" :options="modes" /></label><label><span class="mb-1 block text-[13px] font-medium">Trạng thái</span><MSelect v-model="draft.status" :options="statuses" /></label><label><span class="mb-1 block text-[13px] font-medium">Đơn vị tổ chức</span><MInput v-model="draft.organizer" /></label><label><span class="mb-1 block text-[13px] font-medium">Thời gian bắt đầu</span><MInput v-model="draft.start_time" type="datetime-local" /></label><label><span class="mb-1 block text-[13px] font-medium">Địa điểm</span><MInput v-model="draft.location" /></label><label><span class="mb-1 block text-[13px] font-medium">Ghi chú</span><MTextarea v-model="draft.note" /></label><p v-if="error || localError" role="alert" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ error || localError }}</p></div></div><footer class="shrink-0 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-4 pb-[calc(12px+var(--mds-mobile-safe-bottom))] pt-3"><MButton variant="primary" class="w-full" :loading="saving" @click="submit">Lưu sự kiện</MButton></footer><MDialog v-model="discard" title="Bỏ sự kiện mới?" type="danger" confirm-text="Bỏ thay đổi" @confirm="emit('cancel')"><p>Thông tin chưa lưu sẽ không được giữ lại.</p></MDialog></section></template>
